begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,pg_temp;
select plan(17);
insert into auth.users(id,aud,role,email) values('82800000-0000-4000-8000-000000000066','authenticated','authenticated','task828-clock@example.invalid');
select set_config('request.jwt.claim.role','service_role',true);
create temporary table clock_jobs(label text primary key,id uuid);
create temporary table clock_results(label text primary key,response jsonb);
create temporary table clock_observed(at timestamptz);
insert into clock_jobs select label,(api.svc_ai_tidas_suggestion_enqueue('82800000-0000-4000-8000-000000000066','process',jsonb_build_object('processDataSet',jsonb_build_object('name',label)))#>>'{data,id}')::uuid from unnest(array['reap','claim','backlog','retry','lease_terminal'])label;
update private.worker_jobs j set timeout_at=case when t.label='lease_terminal' then null else clock_timestamp()+case when t.label='reap' then interval '100ms' else interval '200ms' end end from clock_jobs t where t.id=j.id;
update private.worker_jobs j set status='cancelled',cancelled_at=now(),finished_at=now() from clock_jobs t where t.id=j.id and t.label='retry';
update private.worker_jobs j set status='running',attempt_count=max_attempts,started_at=now(),leased_by='task828-clock-orphan',lease_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '200ms' from clock_jobs t where t.id=j.id and t.label='lease_terminal';
select pg_sleep(0.35);
insert into clock_observed values(clock_timestamp());
select ok((select bool_and(timeout_at<clock_timestamp() and timeout_at>now()) from private.worker_jobs j join clock_jobs t using(id)), 'all synthetic deadlines crossed after transaction start');
select is(private.worker_expire_ai_suggestions(1),1,'old caller transaction still reaps one elapsed deadline');
select is((select status from private.worker_jobs j join clock_jobs t on t.id=j.id where t.label='reap'),'cancelled','old transaction expiry selects earliest actual deadline');
select ok((select cancelled_at>=o.at and cancelled_at=finished_at and cancelled_at=updated_at from private.worker_jobs j join clock_jobs t on t.id=j.id cross join clock_observed o where label='reap'),'expiry row timestamps use one fresh actual transition clock');
select ok((select e.created_at=j.cancelled_at from private.worker_job_events e join private.worker_jobs j on j.id=e.job_id join clock_jobs t on t.id=j.id where t.label='reap' and event_type='cancelled'),'expiry audit timestamp matches actual cancellation');
insert into clock_results values('claim',private.worker_claim_jobs('ai','task828-clock',1,900));
select is((select jsonb_array_length(response->'data') from clock_results where label='claim'),0,'long transaction cannot claim elapsed work beyond the bounded reaper visit');
select ok((select status='failed' and error_code='lease_expired_max_attempts' and finished_at>=o.at and updated_at=finished_at from private.worker_jobs j join clock_jobs t on t.id=j.id cross join clock_observed o where label='lease_terminal'),'AI max-attempt lease expiry uses fresh recovery and terminal time');
select ok((select e.created_at=j.finished_at from private.worker_job_events e join private.worker_jobs j on j.id=e.job_id join clock_jobs t on t.id=j.id where label='lease_terminal' and event_type='failed'),'AI lease expiry audit binds the actual terminal transition');
select is((select count(*) from private.worker_jobs j join clock_jobs t using(id) where j.status='queued'),1::bigint,'backlog beyond this call remains queued for later bounded visits');
select is(private.worker_retry_job((select id from clock_jobs where label='retry'))->>'code','WORKER_JOB_DEADLINE_EXPIRED','long transaction retry rejects deadline elapsed in actual time');
select is((select status from private.worker_jobs j join clock_jobs t on t.id=j.id where label='retry'),'cancelled','expired retry rejection preserves terminal status');
insert into clock_jobs select 'fresh',(api.svc_ai_tidas_suggestion_enqueue('82800000-0000-4000-8000-000000000066','process','{"processDataSet":{"name":"fresh"}}')#>>'{data,id}')::uuid;
insert into clock_results values('fresh_claim',private.worker_claim_jobs('ai','task828-clock',1,900));
select is((select response#>>'{data,0,id}' from clock_results where label='fresh_claim'),(select id::text from clock_jobs where label='fresh'),'fresh admission proceeds after expired backlog settlement');
select ok((select started_at>=o.at and updated_at=started_at and heartbeat_at=started_at and lease_expires_at=started_at+interval '900s' from private.worker_jobs j join clock_jobs t on t.id=j.id cross join clock_observed o where label='fresh'),'new AI lease and row timestamps bind the actual locked admission time');
select ok((select e.created_at=j.started_at from private.worker_job_events e join private.worker_jobs j on j.id=e.job_id join clock_jobs t on t.id=j.id where label='fresh' and event_type='claimed'),'claim audit uses the same actual admission time');
select api.svc_worker_cancel_job((select id from clock_jobs where label='fresh'),null,'synthetic fresh retry');
insert into clock_results values('fresh_retry',private.worker_retry_job((select id from clock_jobs where label='fresh')));
select is((select response->>'ok' from clock_results where label='fresh_retry'),'true','unelapsed AI retry remains admitted');
select ok((select e.created_at=j.updated_at and j.run_after=j.updated_at and j.updated_at>=o.at from private.worker_job_events e join private.worker_jobs j on j.id=e.job_id join clock_jobs t on t.id=j.id cross join clock_observed o where label='fresh' and event_type='retried'),'retry audit and scheduling bind actual post-lock time');
insert into clock_jobs select 'solver',(private.worker_enqueue_job(p_job_kind=>'lca.solve_one',p_requested_by=>'82800000-0000-4000-8000-000000000066',p_timeout_at=>now()-interval '1h')#>>'{data,id}')::uuid;
select private.worker_claim_jobs('solver','task828-clock-solver',1,900)->>'ok';
select is((select started_at from private.worker_jobs j join clock_jobs t on t.id=j.id where label='solver'),now(),'non-AI transaction-clock semantics remain unchanged');
select * from finish();
rollback;
